        "file_path": "/private/tmp/rp1-evals/adc92151/workspace/src/lib/yaml-validator.ts",
        "content": "/**\n * YAML validation library for parsing and validating YAML files.\n */\n\nimport yaml from \"js-yaml\";\n\n/**\n * Result for a successfully validated YAML file.\n */\nexport interface ValidationSuccess {\n  valid: true;\n  filePath: string;\n}\n\n/**\n * Result for a YAML file that failed validation.\n */\nexport interface ValidationError {\n  valid: false;\n  filePath: string;\n  error: string;\n  line?: number;\n  column?: number;\n}\n\n/**\n * Union type for validation results.\n */\nexport type ValidationResult = ValidationSuccess | ValidationError;\n\n/**\n * Validate YAML content string.\n *\n * @param content - The YAML content to validate\n * @param filePath - The file path (used for error reporting)\n * @returns ValidationResult indicating success or failure with details\n */\nexport function validateYamlContent(\n  content: string,\n  filePath: string\n): ValidationResult {\n  try {\n    yaml.load(content, { filename: filePath });\n    return { valid: true, filePath };\n  } catch (error) {\n    if (error instanceof yaml.YAMLException) {\n      return {\n        valid: false,\n        filePath,\n        error: error.reason || \"Invalid YAML syntax\",\n        line: error.mark?.line !== undefined ? error.mark.line + 1 : undefined,\n        column:\n          error.mark?.column !== undefined ? error.mark.column + 1 : undefined,\n      };\n    }\n    return {\n      valid: false,\n      filePath,\n      error: \"Unknown parsing error\",\n    };\n  }\n}\n\n/**\n * Validate a YAML file by reading it and checking its syntax.\n *\n * @param filePath - Path to the YAML file to validate\n * @returns Promise resolving to ValidationResult\n */\nexport async function validateYamlFile(\n  filePath: string\n): Promise<ValidationResult> {\n  try {\n    const file = Bun.file(filePath);\n    const exists = await file.exists();\n\n    if (!exists) {\n      return {\n        valid: false,\n        filePath,\n        error: \"file not found\",\n      };\n    }\n\n    const content = await file.text();\n    return validateYamlContent(content, filePath);\n  } catch (error) {\n    return {\n      valid: false,\n      filePath,\n      error:\n        error instanceof Error ? error.message : \"Unknown error reading file\",\n    };\n  }\n}\n"
      },
