      "input": {
        "file_path": "/private/tmp/rp1-evals/adc92151/workspace/src/index.ts",
        "content": "/**\n * CLI entry point and dispatcher for the rp1 CLI.\n * Routes commands to their respective handlers.\n */\n\nimport { getCommand, getAllCommands } from \"./commands\";\nimport type { Command } from \"./commands/types\";\n\nconst CLI_NAME = \"rp1\";\nconst CLI_VERSION = \"1.0.0\";\n\n/**\n * Display global help showing all available commands.\n */\nfunction showGlobalHelp(): void {\n  const commands = getAllCommands();\n\n  console.log(`${CLI_NAME} - CLI tool v${CLI_VERSION}`);\n  console.log(\"\");\n  console.log(\"Usage:\");\n  console.log(`  ${CLI_NAME} <command> [options] [arguments]`);\n  console.log(\"\");\n  console.log(\"Commands:\");\n\n  if (commands.length === 0) {\n    console.log(\"  No commands registered.\");\n  } else {\n    for (const cmd of commands) {\n      console.log(`  ${cmd.name.padEnd(20)} ${cmd.description}`);\n    }\n  }\n\n  console.log(\"\");\n  console.log(\"Options:\");\n  console.log(\"  --help              Show help for a command\");\n  console.log(\"\");\n  console.log(`Run '${CLI_NAME} <command> --help' for more information on a command.`);\n}\n\n/**\n * Display help for a specific command.\n *\n * @param command - The command to show help for\n */\nfunction showCommandHelp(command: Command): void {\n  console.log(`${CLI_NAME} ${command.name}`);\n  console.log(\"\");\n  console.log(command.description);\n  console.log(\"\");\n  console.log(\"Usage:\");\n  console.log(`  ${command.usage}`);\n}\n\n/**\n * Main CLI dispatcher.\n * Parses arguments, routes to commands, and handles exit codes.\n */\nasync function main(): Promise<void> {\n  const args = process.argv.slice(2);\n  const commandName = args[0];\n\n  // No command or global --help\n  if (!commandName || commandName === \"--help\" || commandName === \"-h\") {\n    showGlobalHelp();\n    process.exit(0);\n  }\n\n  // Look up command in registry\n  const command = getCommand(commandName);\n\n  if (!command) {\n    console.error(`Unknown command: ${commandName}`);\n    console.error(\"\");\n    console.error(`Run '${CLI_NAME} --help' to see available commands.`);\n    process.exit(1);\n  }\n\n  // Check for per-command --help\n  const commandArgs = args.slice(1);\n  if (commandArgs.includes(\"--help\") || commandArgs.includes(\"-h\")) {\n    showCommandHelp(command);\n    process.exit(0);\n  }\n\n  // Execute the command\n  const result = await command.execute(commandArgs);\n  process.exit(result.exitCode);\n}\n\n// Run the CLI\nmain();\n"
