        "content": "import { describe, expect, test, beforeEach, afterEach, spyOn } from \"bun:test\";\nimport { join } from \"path\";\nimport { validateYamlCommand } from \"./validate-yaml\";\n\nconst FIXTURES_DIR = join(import.meta.dir, \"../../test/fixtures\");\n\ndescribe(\"validate-yaml command\", () => {\n  let consoleOutput: string[];\n  let consoleErrorOutput: string[];\n  let originalLog: typeof console.log;\n  let originalError: typeof console.error;\n\n  beforeEach(() => {\n    consoleOutput = [];\n    consoleErrorOutput = [];\n    originalLog = console.log;\n    originalError = console.error;\n    console.log = (...args: unknown[]) => {\n      consoleOutput.push(args.map(String).join(\" \"));\n    };\n    console.error = (...args: unknown[]) => {\n      consoleErrorOutput.push(args.map(String).join(\" \"));\n    };\n  });\n\n  afterEach(() => {\n    console.log = originalLog;\n    console.error = originalError;\n  });\n\n  describe(\"single file validation\", () => {\n    test(\"returns exit code 0 and prints valid for a valid file\", async () => {\n      const filePath = join(FIXTURES_DIR, \"valid-simple.yaml\");\n      const result = await validateYamlCommand.execute([filePath]);\n\n      expect(result.exitCode).toBe(0);\n      expect(consoleOutput.some((line) => line.includes(\"valid\"))).toBe(true);\n      expect(consoleOutput.some((line) => line.includes(filePath))).toBe(true);\n    });\n\n    test(\"returns exit code 1 and prints error for an invalid file\", async () => {\n      const filePath = join(FIXTURES_DIR, \"invalid-syntax.yaml\");\n      const result = await validateYamlCommand.execute([filePath]);\n\n      expect(result.exitCode).toBe(1);\n      expect(consoleOutput.some((line) => line.includes(\"error\"))).toBe(true);\n      expect(consoleOutput.some((line) => line.includes(\"line\"))).toBe(true);\n    });\n\n    test(\"returns exit code 1 and prints error for missing file\", async () => {\n      const filePath = join(FIXTURES_DIR, \"does-not-exist.yaml\");\n      const result = await validateYamlCommand.execute([filePath]);\n\n      expect(result.exitCode).toBe(1);\n      expect(\n        consoleOutput.some((line) => line.includes(\"file not found\"))\n      ).toBe(true);\n    });\n  });\n\n  describe(\"multiple file validation\", () => {\n    test(\"returns exit code 0 when all files are valid\", async () => {\n      const file1 = join(FIXTURES_DIR, \"valid-simple.yaml\");\n      const file2 = join(FIXTURES_DIR, \"valid-complex.yaml\");\n      const file3 = join(FIXTURES_DIR, \"empty.yaml\");\n\n      const result = await validateYamlCommand.execute([file1, file2, file3]);\n\n      expect(result.exitCode).toBe(0);\n      expect(consoleOutput.some((line) => line.includes(\"3 valid\"))).toBe(true);\n      expect(consoleOutput.some((line) => line.includes(\"0 invalid\"))).toBe(\n        true\n      );\n    });\n\n    test(\"returns exit code 1 when one file is invalid\", async () => {\n      const validFile = join(FIXTURES_DIR, \"valid-simple.yaml\");\n      const invalidFile = join(FIXTURES_DIR, \"invalid-syntax.yaml\");\n\n      const result = await validateYamlCommand.execute([validFile, invalidFile]);\n\n      expect(result.exitCode).toBe(1);\n      expect(consoleOutput.some((line) => line.includes(\"1 valid\"))).toBe(true);\n      expect(consoleOutput.some((line) => line.includes(\"1 invalid\"))).toBe(\n        true\n      );\n    });\n\n    test(\"validates all files even if first one has error\", async () => {\n      const invalidFile = join(FIXTURES_DIR, \"invalid-syntax.yaml\");\n      const validFile = join(FIXTURES_DIR, \"valid-simple.yaml\");\n\n      const result = await validateYamlCommand.execute([invalidFile, validFile]);\n\n      expect(result.exitCode).toBe(1);\n      expect(\n        consoleOutput.some(\n          (line) =>\n            line.includes(validFile) &&\n            line.includes(\"valid\") &&\n            !line.includes(\"invalid\")\n        )\n      ).toBe(true);\n      expect(\n        consoleOutput.some(\n          (line) => line.includes(invalidFile) && line.includes(\"error\")\n        )\n      ).toBe(true);\n    });\n\n    test(\"returns exit code 1 when a file is missing among valid files\", async () => {\n      const validFile = join(FIXTURES_DIR, \"valid-simple.yaml\");\n      const missingFile = join(FIXTURES_DIR, \"does-not-exist.yaml\");\n\n      const result = await validateYamlCommand.execute([validFile, missingFile]);\n\n      expect(result.exitCode).toBe(1);\n      expect(consoleOutput.some((line) => line.includes(\"1 valid\"))).toBe(true);\n      expect(consoleOutput.some((line) => line.includes(\"1 invalid\"))).toBe(\n        true\n      );\n    });\n  });\n\n  describe(\"no arguments\", () => {\n    test(\"returns exit code 1 and shows usage error\", async () => {\n      const result = await validateYamlCommand.execute([]);\n\n      expect(result.exitCode).toBe(1);\n      expect(\n        consoleErrorOutput.some((line) =>\n          line.includes(\"At least one file path is required\")\n        )\n      ).toBe(true);\n      expect(\n        consoleErrorOutput.some((line) => line.includes(\"Usage\"))\n      ).toBe(true);\n    });\n  });\n\n  describe(\"command metadata\", () => {\n    test(\"has correct name\", () => {\n      expect(validateYamlCommand.name).toBe(\"validate-yaml\");\n    });\n\n    test(\"has description\", () => {\n      expect(validateYamlCommand.description).toBeDefined();\n      expect(validateYamlCommand.description.length).toBeGreaterThan(0);\n    });\n\n    test(\"has usage string\", () => {\n      expect(validateYamlCommand.usage).toBeDefined();\n      expect(validateYamlCommand.usage).toContain(\"validate-yaml\");\n    });\n  });\n});\n"
      },
