/**
 * Command interface definitions for the rp1 CLI.
 */

/**
 * Result returned by command execution.
 */
export interface CommandResult {
  exitCode: number;
}

/**
 * Interface that all CLI commands must implement.
 */
export interface Command {
  /** The command name used to invoke it (e.g., "validate-yaml") */
  name: string;
  /** A brief description of what the command does */
  description: string;
  /** Usage string showing how to invoke the command */
  usage: string;
  /** Execute the command with the given arguments */
  execute(args: string[]): Promise<CommandResult>;
}

/**
 * YAML validation library for parsing and validating YAML files.
 */

import yaml from "js-yaml";

/**
 * Result for a successfully validated YAML file.
 */
export interface ValidationSuccess {
  valid: true;
  filePath: string;
}

/**
 * Result for a YAML file that failed validation.
 */
export interface ValidationError {
  valid: false;
  filePath: string;
  error: string;
  line?: number;
  column?: number;
}

/**
 * Union type for validation results.
 */
export type ValidationResult = ValidationSuccess | ValidationError;

/**
 * Validate YAML content string.
 *
 * @param content - The YAML content to validate
 * @param filePath - The file path (used for error reporting)
 * @returns ValidationResult indicating success or failure with details
 */
export function validateYamlContent(
  content: string,
  filePath: string
): ValidationResult {
  try {
    yaml.load(content, { filename: filePath });
    return { valid: true, filePath };
  } catch (error) {
    if (error instanceof yaml.YAMLException) {
      return {
        valid: false,
        filePath,
        error: error.reason || "Invalid YAML syntax",
        line: error.mark?.line !== undefined ? error.mark.line + 1 : undefined,
        column:
          error.mark?.column !== undefined ? error.mark.column + 1 : undefined,
      };
    }
    return {
      valid: false,
      filePath,
      error: "Unknown parsing error",
    };
  }
}

/**
 * Validate a YAML file by reading it and checking its syntax.
 *
 * @param filePath - Path to the YAML file to validate
 * @returns Promise resolving to ValidationResult
 */
export async function validateYamlFile(
  filePath: string
): Promise<ValidationResult> {
  try {
    const file = Bun.file(filePath);
    const exists = await file.exists();

    if (!exists) {
      return {
        valid: false,
        filePath,
        error: "file not found",
      };
    }

    const content = await file.text();
    return validateYamlContent(content, filePath);
  } catch (error) {
    return {
      valid: false,
      filePath,
      error:
        error instanceof Error ? error.message : "Unknown error reading file",
    };
  }
}

/**
 * Command registry for the rp1 CLI.
 * Registers all available commands for the dispatcher to use.
 */

import type { Command } from "./types";

/**
 * Registry of all available CLI commands.
 * Commands are keyed by their name for O(1) lookup.
 */
export const commands: Record<string, Command> = {
  // Commands will be registered here as they are implemented
  // e.g., "validate-yaml": validateYamlCommand
};

/**
 * Get a command by name from the registry.
 *
 * @param name - The command name to look up
 * @returns The command if found, undefined otherwise
 */
export function getCommand(name: string): Command | undefined {
  return commands[name];
}

/**
 * Get all registered command names.
 *
 * @returns Array of command names
 */
export function getCommandNames(): string[] {
  return Object.keys(commands);
}

/**
 * Get all registered commands.
 *
 * @returns Array of commands
 */
export function getAllCommands(): Command[] {
  return Object.values(commands);
}

/**
 * CLI entry point and dispatcher for the rp1 CLI.
 * Routes commands to their respective handlers.
 */

import { getCommand, getAllCommands } from "./commands";
import type { Command } from "./commands/types";

const CLI_NAME = "rp1";
const CLI_VERSION = "1.0.0";

/**
 * Display global help showing all available commands.
 */
function showGlobalHelp(): void {
  const commands = getAllCommands();

  console.log(`${CLI_NAME} - CLI tool v${CLI_VERSION}`);
  console.log("");
  console.log("Usage:");
  console.log(`  ${CLI_NAME} <command> [options] [arguments]`);
  console.log("");
  console.log("Commands:");

  if (commands.length === 0) {
    console.log("  No commands registered.");
  } else {
    for (const cmd of commands) {
      console.log(`  ${cmd.name.padEnd(20)} ${cmd.description}`);
    }
  }

  console.log("");
  console.log("Options:");
  console.log("  --help              Show help for a command");
  console.log("");
  console.log(`Run '${CLI_NAME} <command> --help' for more information on a command.`);
}

/**
 * Display help for a specific command.
 *
 * @param command - The command to show help for
 */
function showCommandHelp(command: Command): void {
  console.log(`${CLI_NAME} ${command.name}`);
  console.log("");
  console.log(command.description);
  console.log("");
  console.log("Usage:");
  console.log(`  ${command.usage}`);
}

/**
 * Main CLI dispatcher.
 * Parses arguments, routes to commands, and handles exit codes.
 */
async function main(): Promise<void> {
  const args = process.argv.slice(2);
  const commandName = args[0];

  // No command or global --help
  if (!commandName || commandName === "--help" || commandName === "-h") {
    showGlobalHelp();
    process.exit(0);
  }

  // Look up command in registry
  const command = getCommand(commandName);

  if (!command) {
    console.error(`Unknown command: ${commandName}`);
    console.error("");
    console.error(`Run '${CLI_NAME} --help' to see available commands.`);
    process.exit(1);
  }

  // Check for per-command --help
  const commandArgs = args.slice(1);
  if (commandArgs.includes("--help") || commandArgs.includes("-h")) {
    showCommandHelp(command);
    process.exit(0);
  }

  // Execute the command
  const result = await command.execute(commandArgs);
  process.exit(result.exitCode);
}

// Run the CLI
main();

/**
 * validate-yaml command - Validates YAML file syntax.
 */

import type { Command, CommandResult } from "./types";
import { validateYamlFile } from "../lib/yaml-validator";

/**
 * Format a validation result for console output.
 *
 * @param filePath - The file path being reported
 * @param valid - Whether the file is valid
 * @param error - Error message if invalid
 * @param line - Line number if available
 * @returns Formatted output string
 */
function formatResult(
  filePath: string,
  valid: boolean,
  error?: string,
  line?: number
): string {
  if (valid) {
    return `${filePath}: valid`;
  }

  if (line !== undefined) {
    return `${filePath}: error on line ${line} - ${error}`;
  }

  return `${filePath}: error - ${error}`;
}

/**
 * The validate-yaml command implementation.
 */
export const validateYamlCommand: Command = {
  name: "validate-yaml",
  description: "Validate YAML file syntax",
  usage: "rp1 validate-yaml <file> [file2] [file3] ...",

  async execute(args: string[]): Promise<CommandResult> {
    if (args.length === 0) {
      console.error("Error: At least one file path is required.");
      console.error("");
      console.error("Usage:");
      console.error(`  ${this.usage}`);
      return { exitCode: 1 };
    }

    let validCount = 0;
    let invalidCount = 0;

    for (const filePath of args) {
      const result = await validateYamlFile(filePath);

      if (result.valid) {
        console.log(formatResult(filePath, true));
        validCount++;
      } else {
        console.log(formatResult(filePath, false, result.error, result.line));
        invalidCount++;
      }
    }

    if (args.length > 1) {
      console.log("");
      console.log(
        `Validated ${args.length} files: ${validCount} valid, ${invalidCount} invalid`
      );
    }

    return { exitCode: invalidCount > 0 ? 1 : 0 };
  },
};

