        "file_path": "/tmp/hypothesis-yaml-validator/yaml-validator.ts",
        "content": "/**\n * DISPOSABLE CODE - Prototype Custom YAML Validator\n * For hypothesis validation only - not production code\n *\n * Tests whether pattern-based validation can catch common YAML syntax errors\n * without using external libraries like js-yaml\n */\n\ninterface ValidationResult {\n  valid: boolean;\n  errors: string[];\n}\n\n/**\n * Custom YAML validator using pattern-based detection\n * Targets common syntax errors: indentation, quoting, key-value format, special chars\n */\nfunction validateYaml(content: string): ValidationResult {\n  const errors: string[] = [];\n  const lines = content.split('\\n');\n\n  // Track indentation levels\n  let prevIndent = 0;\n  let inMultilineString = false;\n  let multilineIndent = 0;\n\n  for (let i = 0; i < lines.length; i++) {\n    const lineNum = i + 1;\n    const line = lines[i];\n    const originalLine = line;\n\n    // Skip empty lines and comments\n    if (line.trim() === '' || line.trim().startsWith('#')) {\n      continue;\n    }\n\n    // Handle multiline strings (basic detection)\n    if (inMultilineString) {\n      const currentIndent = line.match(/^(\\s*)/)?.[1].length ?? 0;\n      if (currentIndent <= multilineIndent && line.trim() !== '') {\n        inMultilineString = false;\n      } else {\n        continue;\n      }\n    }\n\n    // Check for multiline string indicators\n    if (line.includes(': |') || line.includes(': >')) {\n      inMultilineString = true;\n      multilineIndent = line.match(/^(\\s*)/)?.[1].length ?? 0;\n    }\n\n    // === INDENTATION CHECKS ===\n\n    // Check for tabs (YAML should use spaces)\n    if (line.includes('\\t')) {\n      errors.push(`Line ${lineNum}: Tab character found - YAML requires spaces for indentation`);\n    }\n\n    // Get current indentation\n    const indentMatch = line.match(/^(\\s*)/);\n    const currentIndent = indentMatch ? indentMatch[1].length : 0;\n\n    // Check for odd indentation (common convention is 2-space increments)\n    if (currentIndent > 0 && currentIndent % 2 !== 0) {\n      errors.push(`Line ${lineNum}: Odd indentation (${currentIndent} spaces) - consider using 2-space increments`);\n    }\n\n    // Check for excessive indentation jumps\n    if (currentIndent > prevIndent + 4) {\n      errors.push(`Line ${lineNum}: Indentation increased by ${currentIndent - prevIndent} spaces - likely error`);\n    }\n\n    // === KEY-VALUE FORMAT CHECKS ===\n\n    const trimmed = line.trim();\n\n    // Check for list items\n    if (trimmed.startsWith('- ') || trimmed === '-') {\n      // Valid list item, continue\n      prevIndent = currentIndent;\n      continue;\n    }\n\n    // Check for key-value pairs\n    if (trimmed.includes(':')) {\n      // Check for missing space after colon in key-value\n      const colonMatch = trimmed.match(/^([^:]+):([^\\s])/);\n      if (colonMatch && !trimmed.includes('://') && !trimmed.startsWith('\"') && !trimmed.startsWith(\"'\")) {\n        // Allow URLs and quoted strings\n        const afterColon = colonMatch[2];\n        if (afterColon !== '' && afterColon !== '\"' && afterColon !== \"'\") {\n          errors.push(`Line ${lineNum}: Missing space after colon in key-value pair`);\n        }\n      }\n\n      // Check for duplicate colon issues\n      const colonCount = (trimmed.match(/:/g) || []).length;\n      const urlPattern = /https?:\\/\\//;\n      if (colonCount > 2 && !urlPattern.test(trimmed)) {\n        // Could be a problem, but also could be time values\n        if (!trimmed.match(/\\d{2}:\\d{2}(:\\d{2})?/)) {\n          errors.push(`Line ${lineNum}: Multiple colons detected - possible formatting issue`);\n        }\n      }\n    } else if (!trimmed.startsWith('-') && !trimmed.startsWith('#') && trimmed !== '---' && trimmed !== '...') {\n      // Not a comment, not a list item, not a document marker, should have a colon\n      if (!inMultilineString && prevIndent >= currentIndent) {\n        errors.push(`Line ${lineNum}: Invalid line - expected key:value format or list item`);\n      }\n    }\n\n    // === QUOTING CHECKS ===\n\n    // Check for unbalanced quotes\n    const singleQuotes = (trimmed.match(/'/g) || []).length;\n    const doubleQuotes = (trimmed.match(/\"/g) || []).length;\n\n    if (singleQuotes % 2 !== 0) {\n      errors.push(`Line ${lineNum}: Unbalanced single quotes`);\n    }\n\n    if (doubleQuotes % 2 !== 0) {\n      errors.push(`Line ${lineNum}: Unbalanced double quotes`);\n    }\n\n    // Check for mixed quote styles in same value (potential error)\n    if (singleQuotes > 0 && doubleQuotes > 0) {\n      // This could be intentional, but flag as warning\n      const valueMatch = trimmed.match(/:\\s*(.+)$/);\n      if (valueMatch) {\n        const value = valueMatch[1];\n        if (value.startsWith(\"'\") && value.includes('\"') || value.startsWith('\"') && value.includes(\"'\")) {\n          // Nested quotes - likely intentional\n        }\n      }\n    }\n\n    // === SPECIAL CHARACTER CHECKS ===\n\n    // Check for unquoted special characters that should be quoted\n    const specialChars = /[&*!|>%@`]/;\n    const valueMatch = trimmed.match(/:\\s*(.+)$/);\n    if (valueMatch) {\n      const value = valueMatch[1].trim();\n      if (specialChars.test(value) && !value.startsWith('\"') && !value.startsWith(\"'\")) {\n        // Allow | and > for multiline\n        if (!value.startsWith('|') && !value.startsWith('>')) {\n          errors.push(`Line ${lineNum}: Special character in unquoted value - consider quoting`);\n        }\n      }\n    }\n\n    // Check for invalid key names\n    const keyMatch = trimmed.match(/^([^:]+):/);\n    if (keyMatch) {\n      const key = keyMatch[1].trim();\n      // Keys starting with special chars should be quoted\n      if (specialChars.test(key.charAt(0)) && !key.startsWith('\"') && !key.startsWith(\"'\")) {\n        errors.push(`Line ${lineNum}: Key starts with special character - should be quoted`);\n      }\n    }\n\n    // === STRUCTURE CHECKS ===\n\n    // Check for trailing spaces (common source of issues)\n    if (line.endsWith(' ') || line.endsWith('\\t')) {\n      errors.push(`Line ${lineNum}: Trailing whitespace detected`);\n    }\n\n    prevIndent = currentIndent;\n  }\n\n  // Check for unclosed multiline string at end\n  if (inMultilineString) {\n    errors.push(`End of file: Unclosed multiline string block`);\n  }\n\n  return {\n    valid: errors.length === 0,\n    errors\n  };\n}\n\n// === TEST CORPUS ===\n\n// Invalid YAML files (should detect errors)\nconst invalidYamlFiles: { name: string; content: string; expectedErrors: string[] }[] = [\n  {\n    name: \"invalid-01-tab-indent.yaml\",\n    content: `name: test\n\\tvalue: indented with tab`,\n    expectedErrors: [\"tab\"]\n  },\n  {\n    name: \"invalid-02-bad-indent-jump.yaml\",\n    content: `root:\n  level1:\n          level2: way too much indent`,\n    expectedErrors: [\"indent\"]\n  },\n  {\n    name: \"invalid-03-missing-space-after-colon.yaml\",\n    content: `key:value_no_space\nanother:also_bad`,\n    expectedErrors: [\"space after colon\"]\n  },\n  {\n    name: \"invalid-04-unbalanced-single-quote.yaml\",\n    content: `name: 'unbalanced quote\nother: value`,\n    expectedErrors: [\"unbalanced\"]\n  },\n  {\n    name: \"invalid-05-unbalanced-double-quote.yaml\",\n    content: `description: \"missing end quote\nnext: line`,\n    expectedErrors: [\"unbalanced\"]\n  },\n  {\n    name: \"invalid-06-odd-indentation.yaml\",\n    content: `parent:\n   child: three space indent`,\n    expectedErrors: [\"odd indentation\"]\n  },\n  {\n    name: \"invalid-07-special-char-unquoted.yaml\",\n    content: `command: echo & run\nspecial: *reference`,\n    expectedErrors: [\"special character\"]\n  },\n  {\n    name: \"invalid-08-trailing-space.yaml\",\n    content: `key: value\nanother: also trailing `,\n    expectedErrors: [\"trailing\"]\n  },\n  {\n    name: \"invalid-09-key-special-char.yaml\",\n    content: `*badkey: value\n&another: thing`,\n    expectedErrors: [\"special character\"]\n  },\n  {\n    name: \"invalid-10-no-colon-structure.yaml\",\n    content: `valid: yes\nthis line has no colon and is not a list\nalso: valid`,\n    expectedErrors: [\"invalid line\"]\n  },\n  {\n    name: \"invalid-11-mixed-issues.yaml\",\n    content: `root:\n\\tindented: with tab\n  key:no_space\n  quote: 'unbalanced`,\n    expectedErrors: [\"tab\", \"space after colon\", \"unbalanced\"]\n  },\n  {\n    name: \"invalid-12-multiple-colons-bad.yaml\",\n    content: `weird: key: has: too: many: colons`,\n    expectedErrors: [\"multiple colons\"]\n  }\n];\n\n// Valid YAML files (should NOT produce errors - or minimal warnings)\nconst validYamlFiles: { name: string; content: string }[] = [\n  {\n    name: \"valid-01-simple.yaml\",\n    content: `name: myapp\nversion: 1.0.0\ndescription: A simple app`\n  },\n  {\n    name: \"valid-02-nested.yaml\",\n    content: `database:\n  host: localhost\n  port: 5432\n  name: mydb`\n  },\n  {\n    name: \"valid-03-list.yaml\",\n    content: `items:\n  - apple\n  - banana\n  - cherry`\n  },\n  {\n    name: \"valid-04-quoted-strings.yaml\",\n    content: `message: \"Hello, World!\"\npath: '/usr/local/bin'\nmixed: \"It's working\"`\n  },\n  {\n    name: \"valid-05-url.yaml\",\n    content: `homepage: https://example.com\napi: http://api.example.com:8080/v1`\n  },\n  {\n    name: \"valid-06-multiline.yaml\",\n    content: `description: |\n  This is a multiline\n  string that spans\n  multiple lines\nnext: value`\n  },\n  {\n    name: \"valid-07-complex-nested.yaml\",\n    content: `server:\n  name: production\n  settings:\n    timeout: 30\n    retries: 3\n  endpoints:\n    - /api/v1\n    - /api/v2`\n  },\n  {\n    name: \"valid-08-time-values.yaml\",\n    content: `start_time: \"10:30:00\"\nend_time: \"18:00:00\"\nduration: \"02:30\"`\n  }\n];\n\n// === RUN TESTS ===\n\nconsole.log(\"=\".repeat(60));\nconsole.log(\"YAML VALIDATOR PROTOTYPE - HYPOTHESIS VALIDATION\");\nconsole.log(\"=\".repeat(60));\nconsole.log(\"\");\n\nconsole.log(\"--- INVALID YAML FILES (Should Detect Errors) ---\\n\");\n\nlet invalidDetected = 0;\nlet invalidTotal = invalidYamlFiles.length;\n\nfor (const file of invalidYamlFiles) {\n  const result = validateYaml(file.content);\n  const detectedExpected = file.expectedErrors.some(expected =>\n    result.errors.some(error => error.toLowerCase().includes(expected.toLowerCase()))\n  );\n\n  if (!result.valid && detectedExpected) {\n    invalidDetected++;\n    console.log(`[PASS] ${file.name}`);\n    console.log(`  Errors found: ${result.errors.length}`);\n    result.errors.slice(0, 3).forEach(e => console.log(`    - ${e}`));\n    if (result.errors.length > 3) {\n      console.log(`    ... and ${result.errors.length - 3} more`);\n    }\n  } else {\n    console.log(`[FAIL] ${file.name}`);\n    console.log(`  Expected errors containing: ${file.expectedErrors.join(\", \")}`);\n    console.log(`  Actual errors: ${result.errors.length > 0 ? result.errors.join(\"; \") : \"NONE\"}`);\n  }\n  console.log(\"\");\n}\n\nconsole.log(\"\\n--- VALID YAML FILES (Should NOT Produce Critical Errors) ---\\n\");\n\nlet validPassed = 0;\nlet validTotal = validYamlFiles.length;\nlet falsePositives: string[] = [];\n\nfor (const file of validYamlFiles) {\n  const result = validateYaml(file.content);\n\n  // Filter out warnings vs critical errors\n  const criticalErrors = result.errors.filter(e =>\n    !e.includes(\"consider\") && !e.includes(\"odd indentation\")\n  );\n\n  if (criticalErrors.length === 0) {\n    validPassed++;\n    console.log(`[PASS] ${file.name}`);\n    if (result.errors.length > 0) {\n      console.log(`  Warnings: ${result.errors.join(\"; \")}`);\n    }\n  } else {\n    console.log(`[FAIL - FALSE POSITIVE] ${file.name}`);\n    console.log(`  Unexpected errors: ${criticalErrors.join(\"; \")}`);\n    falsePositives.push(file.name);\n  }\n  console.log(\"\");\n}\n\n// === SUMMARY ===\n\nconsole.log(\"\\n\" + \"=\".repeat(60));\nconsole.log(\"VALIDATION SUMMARY\");\nconsole.log(\"=\".repeat(60));\nconsole.log(\"\");\nconsole.log(`Invalid YAML Detection: ${invalidDetected}/${invalidTotal} (${Math.round(invalidDetected/invalidTotal*100)}%)`);\nconsole.log(`Valid YAML (No False Positives): ${validPassed}/${validTotal} (${Math.round(validPassed/validTotal*100)}%)`);\nconsole.log(\"\");\n\nif (invalidDetected >= 10 && falsePositives.length === 0) {\n  console.log(\"RESULT: HYPOTHESIS CONFIRMED\");\n  console.log(\"Custom pattern-based validation successfully detected errors in 10+ invalid files\");\n  console.log(\"with no false positives on valid YAML configuration files.\");\n} else if (invalidDetected < 10) {\n  console.log(\"RESULT: HYPOTHESIS REJECTED\");\n  console.log(`Only detected ${invalidDetected} of ${invalidTotal} invalid files.`);\n  console.log(\"Custom validation may not be sufficient for catching common YAML errors.\");\n} else if (falsePositives.length > 0) {\n  console.log(\"RESULT: HYPOTHESIS REJECTED\");\n  console.log(`False positives detected on valid files: ${falsePositives.join(\", \")}`);\n  console.log(\"Custom validation produces too many false positives.\");\n}\n\nconsole.log(\"\");\nconsole.log(\"=\".repeat(60));\n"
