        "content": "/**\n * YAML Validator CLI\n *\n * Command-line entry point for validating YAML file syntax.\n * Usage: bun run validate-yaml <file>\n */\n\nimport { validateYamlFile } from \"./yaml-validator\";\n\nconst HELP_TEXT = `YAML Validator - Validate YAML file syntax\n\nUsage: bun run validate-yaml <file>\n\nArguments:\n  file    Path to the YAML file to validate\n\nExit Codes:\n  0       File contains valid YAML syntax\n  1       Validation failed or error occurred`;\n\nasync function main(): Promise<void> {\n  const args = process.argv.slice(2);\n\n  if (args.length === 0) {\n    console.log(HELP_TEXT);\n    process.exit(1);\n  }\n\n  const filePath = args[0];\n  const result = await validateYamlFile(filePath);\n\n  if (result.valid) {\n    console.log(`[OK] ${filePath} is valid YAML`);\n    process.exit(0);\n  }\n\n  if (result.error === \"File not found\") {\n    console.log(`[ERROR] File not found: ${filePath}`);\n    process.exit(1);\n  }\n\n  console.log(`[ERROR] ${filePath}`);\n  if (result.line !== undefined && result.column !== undefined) {\n    console.log(`  Line ${result.line}, Column ${result.column}: ${result.error}`);\n  } else if (result.line !== undefined) {\n    console.log(`  Line ${result.line}: ${result.error}`);\n  } else {\n    console.log(`  ${result.error}`);\n  }\n  process.exit(1);\n}\n\nmain();\n"
