        "file_path": "/private/tmp/rp1-evals/fd49fe37/workspace/.rp1/work/worktrees/feature-yaml-validator/src/yaml-validator.test.ts",
        "content": "import { describe, expect, test, beforeAll, afterAll } from \"bun:test\";\nimport { validateYamlSyntax, validateYamlFile } from \"./yaml-validator\";\nimport { unlink, writeFile } from \"fs/promises\";\nimport { join } from \"path\";\n\ndescribe(\"validateYamlSyntax\", () => {\n  describe(\"valid YAML\", () => {\n    test(\"valid simple key-value YAML returns valid: true\", () => {\n      const yaml = \"key: value\";\n      const result = validateYamlSyntax(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"valid nested structure YAML returns valid: true\", () => {\n      const yaml = `\nparent:\n  child1: value1\n  child2: value2\n  nested:\n    deep: value3\n`;\n      const result = validateYamlSyntax(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"empty file returns valid: true per BR-001\", () => {\n      const result = validateYamlSyntax(\"\");\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"whitespace-only file returns valid: true per BR-001\", () => {\n      const result = validateYamlSyntax(\"   \\n  \\n   \");\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"multi-document YAML returns valid: true per BR-002\", () => {\n      const yaml = `---\nkey1: value1\n---\nkey2: value2\n...`;\n      const result = validateYamlSyntax(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"YAML with comments returns valid: true\", () => {\n      const yaml = `# This is a comment\nkey: value  # inline comment\n# another comment\nnested:\n  # nested comment\n  child: value`;\n      const result = validateYamlSyntax(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"YAML with list items returns valid: true\", () => {\n      const yaml = `items:\n  - item1\n  - item2\n  - item3`;\n      const result = validateYamlSyntax(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"YAML with quoted strings returns valid: true\", () => {\n      const yaml = `\nsingle: 'single quoted'\ndouble: \"double quoted\"\nspecial: \"@special value\"`;\n      const result = validateYamlSyntax(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"YAML with multiline string indicator returns valid: true\", () => {\n      const yaml = `description: |\n  This is a multiline\n  string that spans\n  multiple lines\nnext_key: value`;\n      const result = validateYamlSyntax(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"YAML with flow sequence returns valid: true\", () => {\n      const yaml = `items: [1, 2, 3]`;\n      const result = validateYamlSyntax(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"YAML with flow mapping returns valid: true\", () => {\n      const yaml = `person: {name: John, age: 30}`;\n      const result = validateYamlSyntax(yaml);\n      expect(result.valid).toBe(true);\n    });\n  });\n\n  describe(\"invalid YAML\", () => {\n    test(\"invalid indentation returns valid: false with error and line info\", () => {\n      const yaml = `parent:\n  child1: value1\n   child2: value2`;\n      const result = validateYamlSyntax(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"indentation\");\n      expect(result.line).toBe(3);\n    });\n\n    test(\"tabs in indentation returns valid: false with error and line info\", () => {\n      const yaml = `key:\\n\\tvalue: indented`;\n      const result = validateYamlSyntax(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"Tabs\");\n      expect(result.line).toBe(2);\n      expect(result.column).toBe(1);\n    });\n\n    test(\"invalid key format (missing colon) returns valid: false with error and line info\", () => {\n      const yaml = `key value without colon`;\n      const result = validateYamlSyntax(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"Invalid\");\n      expect(result.line).toBe(1);\n    });\n\n    test(\"unclosed single quote returns valid: false with error\", () => {\n      const yaml = `key: 'unclosed`;\n      const result = validateYamlSyntax(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"Unclosed\");\n      expect(result.line).toBe(1);\n    });\n\n    test(\"unclosed double quote returns valid: false with error\", () => {\n      const yaml = `key: \"unclosed`;\n      const result = validateYamlSyntax(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"Unclosed\");\n      expect(result.line).toBe(1);\n    });\n\n    test(\"invalid special character in unquoted string returns valid: false with error\", () => {\n      const yaml = `key: @invalid`;\n      const result = validateYamlSyntax(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"special character\");\n      expect(result.line).toBe(1);\n    });\n\n    test(\"backtick in unquoted value returns valid: false with error\", () => {\n      const yaml = \"key: `invalid\";\n      const result = validateYamlSyntax(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"special character\");\n    });\n\n    test(\"unclosed bracket in flow sequence returns valid: false with error\", () => {\n      const yaml = `[1, 2, 3`;\n      const result = validateYamlSyntax(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"bracket\");\n    });\n\n    test(\"unclosed brace in flow mapping returns valid: false with error\", () => {\n      const yaml = `{key: value`;\n      const result = validateYamlSyntax(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"brace\");\n    });\n  });\n\n  describe(\"options\", () => {\n    test(\"allowEmpty: false returns error for empty content\", () => {\n      const result = validateYamlSyntax(\"\", { allowEmpty: false });\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"Empty\");\n    });\n  });\n});\n\ndescribe(\"validateYamlFile\", () => {\n  const testDir = \"/tmp/yaml-validator-test\";\n  const validYamlPath = join(testDir, \"valid.yaml\");\n  const invalidYamlPath = join(testDir, \"invalid.yaml\");\n  const nonExistentPath = join(testDir, \"does-not-exist.yaml\");\n\n  beforeAll(async () => {\n    await Bun.write(validYamlPath, \"key: value\\nname: test\");\n    await Bun.write(invalidYamlPath, \"key: @invalid\");\n  });\n\n  afterAll(async () => {\n    try {\n      await unlink(validYamlPath);\n      await unlink(invalidYamlPath);\n    } catch {\n      // Ignore cleanup errors\n    }\n  });\n\n  test(\"file not found returns valid: false with 'File not found' error\", async () => {\n    const result = await validateYamlFile(nonExistentPath);\n    expect(result.valid).toBe(false);\n    expect(result.error).toBe(\"File not found\");\n  });\n\n  test(\"valid file path returns valid: true\", async () => {\n    const result = await validateYamlFile(validYamlPath);\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"invalid file path returns error with details\", async () => {\n    const result = await validateYamlFile(invalidYamlPath);\n    expect(result.valid).toBe(false);\n    expect(result.error).toBeDefined();\n    expect(result.error).toContain(\"special character\");\n  });\n});\n"
