 */
function validateYaml(content: string): ValidationResult {
  const errors: string[] = [];
  const lines = content.split('\n');

  let prevIndent = 0;
  let inMultilineString = false;
  let multilineIndent = 0;

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1;
    const line = lines[i];

    // Skip empty lines and comments
    if (line.trim() === '' || line.trim().startsWith('#')) {
      continue;
    }

    // Handle multiline strings
    if (inMultilineString) {
      const currentIndent = line.match(/^(\s*)/)?.[1].length ?? 0;
      if (currentIndent <= multilineIndent && line.trim() !== '') {
        inMultilineString = false;
      } else {
        continue;
      }
    }

    if (line.includes(': |') || line.includes(': >')) {
      inMultilineString = true;
      multilineIndent = line.match(/^(\s*)/)?.[1].length ?? 0;
    }

    // === INDENTATION CHECKS ===

    if (line.includes('\t')) {
      errors.push(`Line ${lineNum}: Tab character found - YAML requires spaces for indentation`);
    }

    const indentMatch = line.match(/^(\s*)/);
    const currentIndent = indentMatch ? indentMatch[1].length : 0;

    if (currentIndent > 0 && currentIndent % 2 !== 0) {
      errors.push(`Line ${lineNum}: Odd indentation (${currentIndent} spaces) - consider using 2-space increments`);
    }

    if (currentIndent > prevIndent + 4) {
      errors.push(`Line ${lineNum}: Indentation increased by ${currentIndent - prevIndent} spaces - likely error`);
    }

    // === KEY-VALUE FORMAT CHECKS ===

    const trimmed = line.trim();

    if (trimmed.startsWith('- ') || trimmed === '-') {
      prevIndent = currentIndent;
      continue;
    }

    if (trimmed.includes(':')) {
      const colonMatch = trimmed.match(/^([^:]+):([^\s])/);
      if (colonMatch && !trimmed.includes('://') && !trimmed.startsWith('"') && !trimmed.startsWith("'")) {
        const afterColon = colonMatch[2];
        if (afterColon !== '' && afterColon !== '"' && afterColon !== "'") {
          errors.push(`Line ${lineNum}: Missing space after colon in key-value pair`);
        }
      }

      const colonCount = (trimmed.match(/:/g) || []).length;
      const urlPattern = /https?:\/\//;
      if (colonCount > 2 && !urlPattern.test(trimmed)) {
        if (!trimmed.match(/\d{2}:\d{2}(:\d{2})?/)) {
          errors.push(`Line ${lineNum}: Multiple colons detected - possible formatting issue`);
        }
      }
    } else if (!trimmed.startsWith('-') && !trimmed.startsWith('#') && trimmed !== '---' && trimmed !== '...') {
      if (!inMultilineString && prevIndent >= currentIndent) {
        errors.push(`Line ${lineNum}: Invalid line - expected key:value format or list item`);
      }
    }

    // === IMPROVED QUOTING CHECKS ===

    // Extract the value portion after the colon
    const keyValueMatch = trimmed.match(/^[^:]+:\s*(.*)$/);
    const valuePart = keyValueMatch ? keyValueMatch[1] : trimmed;

    // Check for unbalanced quotes - but handle nested quotes properly
    const checkQuoteBalance = (text: string): { singleUnbalanced: boolean; doubleUnbalanced: boolean } => {
      let inSingle = false;
      let inDouble = false;

      for (let j = 0; j < text.length; j++) {
        const char = text[j];
        const prevChar = j > 0 ? text[j - 1] : '';

        // Skip escaped quotes
        if (prevChar === '\\') continue;

        if (char === '"' && !inSingle) {
          inDouble = !inDouble;
        } else if (char === "'" && !inDouble) {
          inSingle = !inSingle;
        }
      }

      return { singleUnbalanced: inSingle, doubleUnbalanced: inDouble };
    };

    const quoteStatus = checkQuoteBalance(valuePart);

    if (quoteStatus.singleUnbalanced) {
      errors.push(`Line ${lineNum}: Unbalanced single quotes`);
    }

    if (quoteStatus.doubleUnbalanced) {
      errors.push(`Line ${lineNum}: Unbalanced double quotes`);
    }

    // === SPECIAL CHARACTER CHECKS ===

    const specialChars = /[&*!|>%@`]/;
    if (keyValueMatch) {
      const value = valuePart.trim();
      if (specialChars.test(value) && !value.startsWith('"') && !value.startsWith("'")) {
        if (!value.startsWith('|') && !value.startsWith('>')) {
          errors.push(`Line ${lineNum}: Special character in unquoted value - consider quoting`);
        }
      }
    }

    const keyMatch = trimmed.match(/^([^:]+):/);
    if (keyMatch) {
      const key = keyMatch[1].trim();
      if (specialChars.test(key.charAt(0)) && !key.startsWith('"') && !key.startsWith("'")) {
        errors.push(`Line ${lineNum}: Key starts with special character - should be quoted`);
      }
    }

    // === TRAILING WHITESPACE ===

    if (line.endsWith(' ') || line.endsWith('\t')) {
      errors.push(`Line ${lineNum}: Trailing whitespace detected`);
    }

    prevIndent = currentIndent;
  }

  if (inMultilineString) {
    errors.push(`End of file: Unclosed multiline string block`);
  }

  return {
    valid: errors.length === 0,
    errors
  };
}

