/**
 * YAML Validator Module
 *
 * Provides YAML syntax validation without external dependencies.
 * Validates common YAML patterns used in configuration files.
 */

export interface ValidationResult {
  valid: boolean;
  error?: string;
  line?: number;
  column?: number;
}

export interface ValidatorOptions {
  allowEmpty?: boolean; // Default: true (per BR-001)
}

const DEFAULT_OPTIONS: ValidatorOptions = {
  allowEmpty: true,
};

/**
 * Validates a YAML file at the given path.
 * Checks file existence, reads content, and validates syntax.
 */
export async function validateYamlFile(
  filePath: string,
  options?: ValidatorOptions
): Promise<ValidationResult> {
  const file = Bun.file(filePath);
  const exists = await file.exists();

  if (!exists) {
    return {
      valid: false,
      error: "File not found",
    };
  }

  const content = await file.text();
  return validateYamlSyntax(content, options);
}

/**
 * Validates YAML syntax from a string content.
 * Checks for common YAML syntax errors including:
 * - Inconsistent indentation
 * - Invalid key-value format
 * - Unclosed quotes
 * - Invalid special characters in unquoted strings
 * - Invalid document markers
 * - List item format
 */
export function validateYamlSyntax(
  content: string,
  options?: ValidatorOptions
): ValidationResult {
  const opts = { ...DEFAULT_OPTIONS, ...options };

  // Handle empty content (valid per BR-001)
  if (content.trim() === "") {
    if (opts.allowEmpty) {
      return { valid: true };
    }
    return {
      valid: false,
      error: "Empty file not allowed",
      line: 1,
      column: 1,
    };
  }

  const lines = content.split("\n");
  const indentStack: number[] = [0];
  let inMultilineString = false;
  let multilineStringIndent = 0;
  let multilineQuoteChar: string | null = null;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const lineNum = i + 1;

    // Skip empty lines
    if (line.trim() === "") {
      continue;
    }

    // Handle document markers (--- and ...)
    if (line.trim() === "---" || line.trim() === "...") {
      continue;
    }

    // Check for tabs (YAML should use spaces)
    const tabIndex = line.indexOf("\t");
    if (tabIndex !== -1) {
      return {
        valid: false,
        error: "Tabs are not allowed in YAML - use spaces for indentation",
        line: lineNum,
        column: tabIndex + 1,
      };
    }

    // Calculate indentation
    const leadingSpaces = line.match(/^( *)/)?.[1].length ?? 0;
    const trimmedLine = line.trim();

    // Skip comment lines
    if (trimmedLine.startsWith("#")) {
      continue;
    }

    // Handle multiline string content
    if (inMultilineString) {
      if (leadingSpaces <= multilineStringIndent && trimmedLine !== "") {
        inMultilineString = false;
        multilineQuoteChar = null;
      } else {
        continue;
      }
    }

    // Check indentation consistency
    const indentCheck = checkIndentation(leadingSpaces, indentStack, lineNum);
    if (!indentCheck.valid) {
      return indentCheck;
    }

    // Check for multiline string indicators (| or >)
    if (trimmedLine.match(/^[^:]+:\s*[|>][-+]?\s*(#.*)?$/)) {
      inMultilineString = true;
      multilineStringIndent = leadingSpaces;
      continue;
    }

    // Check for unclosed quotes
    const quoteCheck = checkQuotes(trimmedLine, lineNum, leadingSpaces);
    if (!quoteCheck.valid) {
      return quoteCheck;
    }

    // Check list items
    if (trimmedLine.startsWith("- ") || trimmedLine === "-") {
      const listCheck = checkListItem(trimmedLine, lineNum, leadingSpaces);
      if (!listCheck.valid) {
        return listCheck;
      }
      continue;
    }

    // Check key-value format
    const kvCheck = checkKeyValueFormat(trimmedLine, lineNum, leadingSpaces);
    if (!kvCheck.valid) {
      return kvCheck;
    }

    // Check for invalid special characters at the start of unquoted values
    const specialCharCheck = checkSpecialCharacters(
      trimmedLine,
      lineNum,
      leadingSpaces
    );
    if (!specialCharCheck.valid) {
      return specialCharCheck;
    }
  }

  // Check for unclosed multiline string at end of file
  if (inMultilineString && multilineQuoteChar) {
    return {
      valid: false,
      error: "Unclosed quoted string at end of file",
      line: lines.length,
      column: 1,
    };
  }

  return { valid: true };
}

/**
 * Checks indentation consistency.
 */
function checkIndentation(
  leadingSpaces: number,
  indentStack: number[],
  lineNum: number
): ValidationResult {
  const currentIndent = indentStack[indentStack.length - 1];

  if (leadingSpaces > currentIndent) {
    // Increased indent - push to stack
    indentStack.push(leadingSpaces);
  } else if (leadingSpaces < currentIndent) {
    // Decreased indent - pop from stack until we find a match
    while (
      indentStack.length > 1 &&
      indentStack[indentStack.length - 1] > leadingSpaces
    ) {
      indentStack.pop();
    }
    // Check if we landed on a valid indent level
    if (indentStack[indentStack.length - 1] !== leadingSpaces) {
      return {
        valid: false,
        error: `Invalid indentation - expected ${indentStack[indentStack.length - 1]} spaces, found ${leadingSpaces}`,
        line: lineNum,
        column: 1,
      };
    }
  }

  return { valid: true };
}

/**
 * Checks for unclosed quotes in a line.
 */
function checkQuotes(
  line: string,
  lineNum: number,
  leadingSpaces: number
): ValidationResult {
  let inSingleQuote = false;
  let inDoubleQuote = false;
  let quoteStartCol = 0;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    const prevChar = i > 0 ? line[i - 1] : "";

    // Skip escaped characters
    if (prevChar === "\\") {
      continue;
    }

    if (char === "'" && !inDoubleQuote) {
      if (inSingleQuote) {
        inSingleQuote = false;
      } else {
        inSingleQuote = true;
        quoteStartCol = i + leadingSpaces + 1;
      }
    } else if (char === '"' && !inSingleQuote) {
      if (inDoubleQuote) {
        inDoubleQuote = false;
      } else {
        inDoubleQuote = true;
        quoteStartCol = i + leadingSpaces + 1;
      }
    }
  }

  if (inSingleQuote || inDoubleQuote) {
    return {
      valid: false,
      error: "Unclosed quoted string",
      line: lineNum,
      column: quoteStartCol,
    };
  }

  return { valid: true };
}

/**
 * Checks list item format.
 */
function checkListItem(
  line: string,
  lineNum: number,
  leadingSpaces: number
): ValidationResult {
  // List items should start with "- " or be just "-"
  if (!line.match(/^-(\s|$)/)) {
    return {
      valid: false,
      error: "Invalid list item format - expected '- ' followed by value",
      line: lineNum,
      column: leadingSpaces + 1,
    };
  }

  return { valid: true };
}

/**
 * Checks key-value format.
 */
function checkKeyValueFormat(
  line: string,
  lineNum: number,
  leadingSpaces: number
): ValidationResult {
  // Skip lines that are just values (like in a list or multiline)
  if (
    line.startsWith("-") ||
    line.startsWith("#") ||
    line === "---" ||
    line === "..."
  ) {
    return { valid: true };
  }

  // Check for valid key-value pattern
  // Key can contain letters, numbers, underscores, hyphens
  // Must be followed by a colon
  const kvMatch = line.match(/^([^:]+):(.*)?$/);

  if (!kvMatch) {
    // Check if this is potentially a flow sequence or mapping
    if (line.startsWith("[") || line.startsWith("{")) {
      return checkFlowSyntax(line, lineNum, leadingSpaces);
    }

    // If it doesn't look like a key-value and isn't a special construct
    if (!line.match(/^[\w\-_.]+$/)) {
      return {
        valid: false,
        error: "Invalid YAML format - expected key: value pattern",
        line: lineNum,
        column: leadingSpaces + 1,
      };
    }
  }

  // Check key format
  if (kvMatch) {
    const key = kvMatch[1].trim();
    // Key should not start with certain special characters unless quoted
    if (key.match(/^[@`]/) && !key.match(/^['"].*['"]$/)) {
      return {
        valid: false,
        error: `Invalid key format - keys starting with special characters must be quoted`,
        line: lineNum,
        column: leadingSpaces + 1,
      };
    }
  }

  return { valid: true };
}

/**
 * Checks for invalid special characters in unquoted values.
 */
function checkSpecialCharacters(
  line: string,
  lineNum: number,
  leadingSpaces: number
): ValidationResult {
  const kvMatch = line.match(/^([^:]+):\s*(.*)$/);

  if (kvMatch) {
    const value = kvMatch[2].trim();

    // Skip if value is empty, quoted, or a comment
    if (
      value === "" ||
      value.startsWith("#") ||
      value.startsWith("'") ||
      value.startsWith('"') ||
      value === "|" ||
      value === ">" ||
      value.startsWith("|") ||
      value.startsWith(">")
    ) {
      return { valid: true };
    }

    // Skip if value is a flow sequence or mapping
    if (value.startsWith("[") || value.startsWith("{")) {
      return { valid: true };
    }

    // Check for special characters that need quoting at the start
    // @, `, and backtick require quoting
    if (value.match(/^[@`]/)) {
      const colonPos = line.indexOf(":");
      return {
        valid: false,
        error: `Invalid value - special character '${value[0]}' at start of value must be quoted`,
        line: lineNum,
        column: leadingSpaces + colonPos + 2,
      };
    }
  }

  return { valid: true };
}

/**
 * Basic check for flow syntax (inline arrays and objects).
 */
function checkFlowSyntax(
  line: string,
  lineNum: number,
  leadingSpaces: number
): ValidationResult {
  let bracketCount = 0;
  let braceCount = 0;
  let inQuote = false;
  let quoteChar = "";

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    const prevChar = i > 0 ? line[i - 1] : "";

    // Handle quotes
    if ((char === '"' || char === "'") && prevChar !== "\\") {
      if (!inQuote) {
        inQuote = true;
        quoteChar = char;
      } else if (char === quoteChar) {
        inQuote = false;
        quoteChar = "";
      }
      continue;
    }

    if (inQuote) continue;

    if (char === "[") bracketCount++;
    if (char === "]") bracketCount--;
    if (char === "{") braceCount++;
    if (char === "}") braceCount--;
  }

  if (bracketCount !== 0) {
    return {
      valid: false,
      error: "Unclosed bracket in flow sequence",
      line: lineNum,
      column: leadingSpaces + 1,
    };
  }

  if (braceCount !== 0) {
    return {
      valid: false,
      error: "Unclosed brace in flow mapping",
      line: lineNum,
      column: leadingSpaces + 1,
    };
  }

  return { valid: true };
}

